<template><view v-if="visible" class="sheet-mask" @click="$emit('close')"><view class="sheet-panel" @click.stop><view class="sheet-handle"/><text class="sheet-title">排序方式</text><button v-for="item in assetSortOptions" :key="item.value" :class="['sort-item',{active:modelValue===item.value}]" @click="choose(item.value)"><text>{{ item.label }}</text><text>{{ modelValue===item.value?'✓':'' }}</text></button><button class="cancel-button" @click="$emit('close')">取消</button></view></view></template>
<script setup lang="ts">import { assetSortOptions,type AssetSort } from "../../features/assets/types";defineProps<{visible:boolean;modelValue:AssetSort}>();const emit=defineEmits<{close:[];"update:modelValue":[value:AssetSort]}>();function choose(value:AssetSort){emit("update:modelValue",value);emit("close");}</script>
<style scoped>.sheet-mask{position:fixed;z-index:180;inset:0;display:flex;align-items:flex-end;background:rgba(23,27,39,.38)}.sheet-panel{width:100%;box-sizing:border-box;padding:10px 18px calc(16px + env(safe-area-inset-bottom));border-radius:24px 24px 0 0;background:#fff}.sheet-handle{width:42px;height:4px;margin:0 auto 12px;border-radius:4px;background:#d5d7de}.sheet-title{display:block;margin-bottom:8px;color:#252a39;font-size:17px;font-weight:700}.sort-item,.cancel-button{display:flex;width:100%;height:46px;margin:0;padding:0 4px;align-items:center;justify-content:space-between;border:0;border-bottom:1px solid #eef0f4;color:#555d70;background:#fff;font-size:12px;text-align:left}.sort-item::after,.cancel-button::after{display:none}.sort-item.active{color:#5a4db2;font-weight:650}.cancel-button{margin-top:8px;justify-content:center;border:0;border-radius:14px;background:#f3f4f7}
</style>
